steps.action:
curl -s -X POST 'https://slack.com/api/conversations.list' --data-urlencode 'token=<TOKEN>' --data-urlencode 'types=public_channel' --data-urlencode 'limit=1000' | python3 -c '
import sys, json
data = json.load(sys.stdin)
if not data.get("ok"):
    print("ERROR", data)
    sys.exit(0)
for c in data.get("channels", []):
    if c.get("name") == "deploys":
        print(c["id"], "|", c.get("name"), "|", c.get("is_archived"))
'
